__version__ = "3.4.0"


class SettlementSchema:
    """Defines the fields and ordering for a settlement claim record."""

    # Default fields in the order they should appear
    _fields = ["claim_id", "amount", "currency"]

    @property
    def fields(self):
        """Return the ordered list of schema fields."""
        return list(self._fields)

    @classmethod
    def current(cls):
        """Return the current settlement schema instance.

        This is the primary entry point used by clients to obtain
        the active settlement schema.
        """
        return cls()
